-- Smart gaps:
-- 1 tiled window  -> larger margin around the window
-- 2+ tiled windows -> minimal gaps between windows

hl.workspace_rule({
    workspace = "w[tv1]",
    gaps_out = 8, -- minimal padding from screen edge
    gaps_in = 4,  -- small gap between windows
})

hl.workspace_rule({
    workspace = "f[1]",
    gaps_out = 8,
    gaps_in = 4,
})

-- Rounded corners, no borders
hl.window_rule({
    name = "rounded-no-border",
    match = {
        float = false,
    },
    border_size = 0,
    rounding = 10,
})


