-----------------------------
---- MOBILE RIGHT LAYOUT ----
-----------------------------

local mobile_mode = false
local mobile_window = nil

-- Your monitor is 1920x1200 @ 1.5 scale.
-- Firefox measured:
--   381 Hyprland units -> ~500 CSS px
--
-- Therefore ~300 Hyprland units gives approximately
-- a 390px CSS viewport.
local MOBILE_WIDTH = 300


hl.layout.register("mobile-right", {

    recalculate = function(ctx)

        local targets = ctx.targets
        local area = ctx.area

        local mobile = nil
        local others = {}


        --------------------------------------------------
        -- Find the window selected for mobile mode
        --------------------------------------------------

        for _, target in ipairs(targets) do

            local win = target.window

            if win
                and mobile_window
                and tostring(win.address) == tostring(mobile_window)
            then

                mobile = target

            else

                table.insert(others, target)

            end

        end


        --------------------------------------------------
        -- Safety fallback
        --------------------------------------------------

        if not mobile then

            for i, target in ipairs(targets) do
                target:place(ctx:column(i, #targets))
            end

            return

        end


        --------------------------------------------------
        -- Mobile width
        --------------------------------------------------

        local mobile_width = math.min(MOBILE_WIDTH, area.w)

        local left_width = area.w - mobile_width


        --------------------------------------------------
        -- LEFT SIDE
        --
        -- All other windows occupy the remaining area.
        --------------------------------------------------

        if #others > 0 and left_width > 0 then

            local each_height = area.h / #others

            for i, target in ipairs(others) do

                target:place({
                    x = area.x,
                    y = area.y + ((i - 1) * each_height),
                    w = left_width,
                    h = each_height,
                })

            end

        end


        --------------------------------------------------
        -- RIGHT SIDE
        --
        -- Selected window gets the complete usable height.
        --------------------------------------------------

        mobile:place({

            x = area.x + left_width,
            y = area.y,

            w = mobile_width,
            h = area.h,

        })

    end,

})


-----------------------------
---- SUPER + M --------------
-----------------------------

hl.bind("SUPER + M", function()

    local win = hl.get_active_window()

    if not win then
        return
    end


    --------------------------------------------------
    -- ENTER MOBILE MODE
    --------------------------------------------------

    if not mobile_mode then

        mobile_window = tostring(win.address)

        mobile_mode = true


        -- Activate our custom layout on the current
        -- workspace.
        hl.workspace_rule({
            workspace = tostring(hl.get_active_workspace().id),
            layout = "lua:mobile-right",
        })


    --------------------------------------------------
    -- EXIT MOBILE MODE
    --------------------------------------------------

    else

        mobile_mode = false
        mobile_window = nil


        -- Return to Hyprland's normal layout using
        -- the workspace rule.
        --
        -- Change this to your normal layout if needed.
        hl.workspace_rule({
            workspace = tostring(hl.get_active_workspace().id),
            layout = "dwindle",
        })

    end

end)


